#!/usr/bin/env bash
# Question 4: HTTPS Gateway. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl get ingressclass traefik >/dev/null 2>&1 && kubectl get gatewayclass traefik >/dev/null 2>&1 || {
  echo "this cluster image has no Traefik or Gateway API: rebuild images with ./cka images build --force" >&2
  exit 1
}
rm -rf /opt/course/tls/${Q4_NS}
mkdir -p /opt/course/tls/${Q4_NS}
chown -R ubuntu:ubuntu /opt/course
mkdir -p /opt/course/tls/${Q4_NS}
openssl req -x509 -newkey rsa:2048 -nodes -days 30 -subj "/CN=secure.${Q4_NS}.lab" -addext "subjectAltName=DNS:secure.${Q4_NS}.lab" -keyout /opt/course/tls/${Q4_NS}/tls.key -out /opt/course/tls/${Q4_NS}/tls.crt 2>/dev/null
chown -R ubuntu:ubuntu /opt/course
kubectl create namespace "${Q4_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q4_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q4_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q4_NS}" create deployment web --image=nginx:1.27-alpine --port=80 --dry-run=client -o yaml | kubectl apply -f - >/dev/null
kubectl -n "${Q4_NS}" expose deployment web --port=80 --dry-run=client -o yaml | kubectl apply -f - >/dev/null
kubectl -n "${Q4_NS}" delete gateway web-gw --ignore-not-found >/dev/null 2>&1 || true
kubectl -n "${Q4_NS}" rollout status deployment/web --timeout=180s >/dev/null
: "${Q4_NS}"
